def eulerian_number(n, m):
    if m == 0:
        return 1 if n == m else 0
    if m == n:
        return 1
    triangle = [[0] * (m + 1) for _ in range(n + 1)]
    triangle[1][1] = 1
    for i in range(2, n + 1):
        triangle[i][1] = i * triangle[i - 1][1]
        for j in range(2, min(i, m) + 1):
            triangle[i][j] = (i - 1) * triangle[i - 1][j - 1] + (j + 1) * triangle[i - 1][j]
    return triangle[n][m]

