    for i in range(2, n + 1):
        triangle[i][1] = i * triangle[i - 1][1]
        for j in range(2, min(i, m) + 1):
            triangle[i][j] = (i - 1) * triangle[i - 1][j - 1] + (j + 1) * triangle[i - 1][j]
    return triangle[n][m]

