def find_integers(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        if x == 0:
            return y, 0, 1
        gcd, s1, t1 = extended_gcd(y % x, x)
        s = t1 - (y // x) * s1
        t = s1
        return gcd, s, t

    gcd_value, s, t = extended_gcd(abs(a), abs(b))
    if n % gcd_value != 0:
        return None

    x = s * (n // gcd_value) * (1 if a > 0 else -1)
    y = t * (n // gcd_value) * (1 if b > 0 else -1)

    return (x, y)

