def find_sequences(m, n):
    if m < 1 or n < 1:
        return 0
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i][j - 1]
            for k in range(1, j // 2 + 1):
                dp[i][j] += dp[i - 1][k]
    return dp[n][m]

