def combinations_with_repetition(lst, n):
    if n == 0:
        return [()]
    if not lst:
        return []
    first_element = lst[0]
    rest_elements = lst[1:]
    with_first = [(first_element,) + comb for comb in combinations_with_repetition(lst, n - 1)]
    without_first = combinations_with_repetition(rest_elements, n)
    return with_first + without_first

